const url = 'http://host.docker.internal:3000/vercel.svg';
const response = await fetch(url);
const blob = await response.blob();
const imageMetadata = await blob.arrayBuffer();
// Extract metadata using OpenCode's tools or shell commands
// Since OpenCode does not have direct tools for image metadata extraction, I will use shell commands to inspect the image.
const imagePath = `/tmp/vercel.svg`;
const fs = require('fs').promises;

// Write the image to a file
await fs.writeFile(imagePath, imageMetadata);

// Use shell commands to extract metadata
const metadataCommand = `exiftool -json -ext svg -c "${imagePath}"`;
const metadataResult = await shell(metadataCommand, { background: false });

// Parse the metadata output
const metadata = JSON.parse(metadataResult.stdout.trim());

